// GPU 호출이 아닌, 이 단원의 명시적 계약을 검증하는 결정적 CPU 모델이다.
static unsigned checks = 0;
void Check(bool condition, const char* name) {
    ++checks;
    if (!condition) throw std::runtime_error(name); // Release에서도 검사를 유지한다.
}
template < class F > void Reject(F action, const char* name) {
    bool rejected = false;
    try {
        action();
    } catch (const std::exception&) {
        rejected = true;
    }
    Check(rejected, name);
}

enum class State { Common, CopyDest, PixelRead, RenderTarget, Uav };
// 잘못된 before 상태는 실제 추적 상태를 바꾸기 전에 거절한다.
struct Resource {
    State state = State::Common;
    void Transition(State before, State after) {
        if (state != before) throw std::logic_error("before state mismatch");
        state = after;
    }
    void Sample() const { if (state != State::PixelRead) throw std::logic_error("not readable");
    }
    void Draw() const { if (state != State::RenderTarget) throw std::logic_error("not RTV");
    }
};
int main() {
    try {
        Resource r;
        Reject([&] { r.Sample(); }, "no implicit promotion in model");
        r.Transition(State::Common, State::CopyDest);
        Check(r.state == State::CopyDest, "copy dest");
        Reject([&] { r.Transition(State::Common, State::PixelRead); }, "incorrect before");
        Check(r.state == State::CopyDest, "failure preserves tracked state");
        r.Transition(State::CopyDest, State::PixelRead);
        r.Sample();
        Check(true, "read after transition");
        Reject([&] { r.Draw(); }, "SRV not RTV");
        r.Transition(State::PixelRead, State::RenderTarget);
        r.Draw();
        Check(true, "render target");
        r.Transition(State::RenderTarget, State::Common);
        Check(r.state == State::Common, "present/common conceptual endpoint");
        std::cout << "PASS DX12-08: " << checks << " CPU contract checks\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}

inline void Transition(ID3D12GraphicsCommandList* list, ID3D12Resource* resource,
    D3D12_RESOURCE_STATES before, D3D12_RESOURCE_STATES after) {
    if (before == after) return;
    D3D12_RESOURCE_BARRIER barrier{};
    barrier.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    barrier.Transition = {resource, D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES, before, after};
    list->ResourceBarrier(1, &barrier);
}
struct DeviceContext {
    ComPtr<IDXGIFactory6> factory;
    ComPtr<ID3D12Device> device;
    explicit DeviceContext(bool warp) {
        UINT factoryFlags = 0;
#ifndef NDEBUG
        // 개발 시 Graphics Tools 설치가 없으면 명확히 실패한다. 검증을 조용히 끄지 않는다.
        ComPtr<ID3D12Debug> debug;
        Check(D3D12GetDebugInterface(IID_PPV_ARGS(debug.GetAddressOf())), "D3D12 debug layer unavailable");
        debug->EnableDebugLayer(); factoryFlags = DXGI_CREATE_FACTORY_DEBUG;
#endif
        Check(CreateDXGIFactory2(factoryFlags, IID_PPV_ARGS(factory.GetAddressOf())), "CreateDXGIFactory2");
        ComPtr<IDXGIAdapter1> adapter;
        if (warp) {
            Check(factory->EnumWarpAdapter(IID_PPV_ARGS(adapter.GetAddressOf())), "EnumWarpAdapter");
            Check(D3D12CreateDevice(adapter.Get(), D3D_FEATURE_LEVEL_11_0,
                IID_PPV_ARGS(device.GetAddressOf())), "Create WARP device");
        } else {
            for (UINT index = 0; ; ++index) {
                adapter.Reset();
                HRESULT hr = factory->EnumAdapters1(index, adapter.GetAddressOf());
                if (hr == DXGI_ERROR_NOT_FOUND) break;
                Check(hr, "EnumAdapters1");
                DXGI_ADAPTER_DESC1 desc{}; Check(adapter->GetDesc1(&desc), "GetDesc1");
                if ((desc.Flags & DXGI_ADAPTER_FLAG_SOFTWARE) != 0) continue;
                if (SUCCEEDED(D3D12CreateDevice(adapter.Get(), D3D_FEATURE_LEVEL_11_0,
                    IID_PPV_ARGS(device.GetAddressOf())))) break;
            }
            if (!device) throw std::runtime_error("No D3D12 hardware adapter. Retry explicitly with --warp.");
        }
        Check(device->SetName(L"ATLAS original educational device"), "SetName(device)");
    }
};
